#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""FINANCE_PLUS_UNICO DESKTOP V1.0 - repository bootstrap.

This file embeds the verified standalone desktop source generated for FinancePlus.
Run normally to start the desktop application.
Run with --extract-source to write the readable standalone source next to this file.
"""
from __future__ import annotations

import base64
import sys
import zlib
from pathlib import Path

_PAYLOAD = """[... ELLIPSIZATION ...]"""

_SOURCE = zlib.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")

if "--extract-source" in sys.argv:
    target = Path(__file__).with_name("FINANCE_PLUS_UNICO_DESKTOP_READABLE.py")
    target.write_text(_SOURCE, encoding="utf-8")
    print(f"Source extracted to: {target}")
    raise SystemExit(0)

_globals = {
    "__name__": "__main__",
    "__file__": str(Path(__file__).resolve()),
    "__package__": None,
}
exec(compile(_SOURCE, "FINANCE_PLUS_UNICO_DESKTOP.py", "exec"), _globals)
